- (void)insertNodeWithValue:(NSInteger)value;
- (BOOL)findValue:(NSInteger)value;

@end

@implementation TernaryTree

- (void)insertNodeWithValue:(NSInteger)value {
    self.root = [self insertNode:self.root withValue:value];
}

- (TreeNode *)insertNode:(TreeNode *)node withValue:(NSInteger)value {
    if (node == nil) {
        node = [[TreeNode alloc] initWithValue:value];
    } else if (value < node.value) {
        node.left = [self insertNode:node.left withValue:value];
    } else if (value == node.value) {
        node.middle = [self insertNode:node.middle withValue:value];
    } else {
        node.right = [self insertNode:node.right withValue:value];
    }
    return node;
}

