    int right = size - 1; // End of the array
    int changes = 0; // Counter for changes made

    while (left <= right) {
        // Check if current left and right elements are not equal
        if (arr[left] != arr[right]) {
            limit--; // decrement the limit

            // Update elements to make them equal, choose larger one to minimize changes.
            if (arr[left] < arr[right]) {
