1. fopen() the file in binary mode ("rb"). Use fread() to read the data in chunks (for example, in 1MB chunks) and count the total bytes read.

2. Use platform-specific functions to get the file size. In Windows, for example, you can use GetFileSizeEx() to get a file size that may exceed the range of a 32-bit integer. In Linux, you can use the stat() system call.

Here is an example of how to change the seek to handle larger files in a platform-independent way:

```c
#include <stdio.h>

#if defined(_WIN32) || defined(_WIN64)
#   include <windows.h>
#else
#   include <unistd.h>
#   include <sys/stat.h>
#endif

long long FileSize(const char *filename)
{
#if defined(_WIN32) || defined(_WIN64)
    HANDLE hFile = CreateFileA(filename, GENERIC_READ, 
        FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 
        FILE_ATTRIBUTE_NORMAL, NULL);
    if (hFile==INVALID_HANDLE_VALUE) 
        return -1; // error condition, could call GetLastError to find out more

    LARGE_INTEGER size;
    if (!GetFileSizeEx(hFile, &size))
    {
        CloseHandle(hFile);
        return -1; // error condition, could call GetLastError to find out more
    }

    CloseHandle(hFile);
    return size.QuadPart;
#else
    struct stat st; 
    if (stat(filename, &st) == 0)
        return st.st_size;

    return -1; // error condition, could call strerror(errno) to find out more
#endif
}

int main()
{
    printf("%lld\n", FileSize("largefile"));
    return 0;
