#include <stdio.h>

int partition(int array[], int low, int high) {
    int pivot = array[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (array[j] <= pivot) {
            i++;
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
    int temp = array[i+1];
    array[i+1] = array[high];
    array[high] = temp;

    return (i + 1);
}

int quickselect(int array[], int k, int low, int high) {
    if (low < high) {
        int pivot = partition(array, low, high);
        if (pivot == k)
            return array[k];
        else if (pivot > k)
            return quickselect(array, k, low, pivot - 1);
        else
            return quickselect(array, k, pivot + 1, high);
    }
    return array[k];
}

float median(int array[], int n) {
    if(n % 2 == 1) 
        return quickselect(array, n/2, 0, n - 1);
    else 
        return (quickselect(array, n/2 - 1, 0, n - 1) + quickselect(array, n/2, 0, n - 1)) / 2.0;
}

int main() {
    int arr[] = {12, 3, 5, 7, 4, 19, 26};
    int n = sizeof(arr) / sizeof(arr[0]);
    printf("Median: %f\n", median(arr, n));
    return 0;
}
