from collections import Counter, OrderedDict

class OrderedCounter(Counter, OrderedDict):
    'Counter that remembers the order elements are first encountered'
    pass

def multilingual_histogram(s):
    # Create a case-insensitive counter
    counter = OrderedCounter(s.lower())

    # Remove spaces from the counter
    if ' ' in counter:
        del counter[' ']

    # Define a comparator for sorting the dictionary
    def comparator(item):
        # Negative frequency for descending order
        # Original order of appearance for same frequency characters
        return -item[1], s.index(item[0])

    # Create the sorted items list
    sorted_items = sorted(counter.items(), key=comparator)

    # Convert the sorted items list into the dictionary
    sorted_dict = OrderedDict(sorted_items)

    return sorted_dict

# Testing
