#include <stdlib.h>

int validateBin(char *binary){
    for(int i = 0; i < strlen(binary); i++)
        if(binary[i] != '0' && binary[i] != '1')
            return 0;
    return 1;
}

int main(void){
    unsigned int num;
    char binary[33];
    scanf("%s",binary);

    if(!validateBin(binary)){
        printf("Error: input is not a binary number.\n");
        return 1;
    }
    if(strlen(binary) > 32){
        printf("Error: input more than 32 bits.\n");
        return 1;
    }

    // Handles binary numbers represented in 2's complement
    if(binary[0] == '1'){
        for(int i = 0; i < strlen(binary); i++)
            binary[i] = binary[i] == '1' ? '0' : '1';

        num = strtoul(binary, NULL, 2);

        // Add 1 at the end to make 2's complementation as negative number
        num = (num + 1);
        num *= -1;
    } else{
        num = strtoul(binary, NULL, 2);
    }

    printf("%X\n", num);   // Print the hexadecimal value
    return 0;
}
```

