Here's a modified version of your function:

```c
#include <fcntl.h>

void spawn(char *const argv[]) {
    int devnull;

    switch (fork()) {
        case 0:
            sigprocmask(SIG_UNBLOCK, &set, NULL);
            setsid();

            devnull = open("/dev/null", O_RDWR);
            if (devnull == -1) {
                perror("open");
                _exit(1);
            }

            // Redirect stdin, stdout, stderr to /dev/null
            dup2(devnull, STDIN_FILENO);
            dup2(devnull, STDOUT_FILENO);
            dup2(devnull, STDERR_FILENO);

            // Close the file descriptor as it is no longer needed
            close(devnull);

            execvp(argv[0], argv);

            perror("execvp");
            _exit(1);
        case -1:
            perror("fork");
            break;
        default:
            break;
    }
}
```
This modified version will redirect the child process's standard input, output, and error file descriptors to `/dev/null` first so that no I/O happens. This happens just before calling `execvp()`, so that the new process spawned will use these new file descriptors.

