void findLongestString(char* strings[], int numberOfStrings, char* prefixSuffix[]) {
    char* longestString = "";
    int totalSum = 0;

    // maps a-z to 1-26, useful for sum computation
    for (unsigned char ch = 'a', num = 1; ch <= 'z'; ch++, num++) {
        char_to_int[ch - 'a'] = num;
    }

    for (int i = 0; i < numberOfStrings; i++) {
        char *s = strings[i];

        if (strncasecmp(s, prefixSuffix[0], strlen(prefixSuffix[0])) == 0 
            && ends_with(s, prefixSuffix[1]) 
                && strlen(s) >= strlen(longestString)) {

            // Record the longest string and compute sum of its characters
            longestString = s;
            totalSum = calculateTotalSum(s);
