void printDiagonalMultiplicationTable(int n) {
    int table[n][n];

    // Generate multiplication table using a single loop
    int num = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            table[i - j][j] = num * num;
            num++;
        }
    }

    // Print the multiplication table in diagonal format
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            printf("%d ", table[i - j][j]);
        }
        printf("\n");
    }
