#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void selectionSort(int arr[], int n) {
    int i, j, maxIndex;

    for (i = 0; i < n-1; i++) {
        maxIndex = i;
        for (j = i+1; j < n; j++) {
            if (arr[j] > arr[maxIndex]) {
                maxIndex = j;
            }
        }
        swap(&arr[i], &arr[maxIndex]);
    }
}

