            p++;
        }
        if (expNegative) {
            result /= pow(10, exp);
        } else {
            result *= pow(10, exp);
        }
    }

    // Set endptr and return the result
    if (hasDigits) {
        end = (char*)p;
        if (endptr != NULL) {
            *endptr = end;
        }
        return negative ? -result : result;
    } else {
        if (endptr != NULL) {
            *endptr = (char*)str;
        }
        return 0.0;
    }
}
```"}]

